event ue_ref;call super::ue_ref;String ls_dzr,ls_mess,ls_yf
Long ll_find,ll_count1,ll_count2,ll_count3,ll_count4,ll_rowcount
Dec {2}  ld_dnzhzfze,ld_lnzhzfze,ld_ybzfxjzfze,ld_tczfze,ld_gbzfze,ld_jzzfze,ld_zyjjzfze,ld_zje,ld_jmybjjzfze
Dec {2} ld_mztotal,ld_zytotal,ld_total_mzghmx,ld_total_mzypmx,ld_total_mzzlmx,ld_total_zyypmx,ld_total_zyzlmx
Dec {2} ld_sddnzhzfze,ld_sdlnzhzfze,ld_sdybzfxjzfze,ld_sdtczfze,ld_sdgbzfze,ld_sdjzzfze,ld_sdzyjjzfze,ld_sdjmybjjzfze
Dec {2} ld_sdmztotal,ld_zzlje

IF em_1.getdate( ) >= Date(gf_server_date()) THEN
	MessageBox('提示','不能对当日及其之后的时间进行统计!')
	RETURN
END IF
idt_begin = em_1.getdatetime(1)
idt_end = DateTime(RelativeDate(em_1.getdate(),1),Time(00:00:00))

//获取统计月份
ls_yf = String(em_1.getdate( ),'yyyymm')
ls_dzr = String(em_1.getdate( ),'yyyymmdd')
is_dzr = ls_dzr
tab_1.tabpage_1.dw_jymx.Reset()
//显示交易明细
tab_1.tabpage_1.dw_jymx.Retrieve(idt_begin,idt_end)
tab_1.tabpage_1.dw_jymx.SetSort("jssj asc")
tab_1.tabpage_1.dw_jymx.Sort()
IF tab_1.tabpage_1.dw_jymx.RowCount( ) <= 0 THEN
	MessageBox('提示','该天没有社保交易明细！')
	SetNull(is_dzr)
	RETURN
END IF
//有社保明细再进行判断计算reset()
dw_1.Reset()
tab_1.tab_dzwj.dw_dzwj.Reset()
tab_1.tab_ghmx.dw_ghmx.Reset()
tab_1.tab_ypmx.dw_ypmx.Reset()
tab_1.tab_zlmx.dw_zlmx.Reset()
tab_1.tab_gzxx.dw_gzxx.Reset()
tab_1.tab_dzxx.dw_dzxx.Reset()
//显示本月对账信息
tab_1.tab_dzxx.dw_dzxx.Retrieve(ls_yf)

//dw_toolbar.Enabled = False

//对对账结果进行判断，有记录则不再判断，无记录则对社保交易明细与fpk等是否保持一致
ll_rowcount = dw_1.Retrieve( is_dzr)
IF ll_rowcount > 0 THEN
	SELECT Sum(zlje) Into :ld_zzlje From sb_jymx Where XMLB = 'GH' And zxlsh Is Not Null And jssj >= :idt_begin And jssj < :idt_end;
	dw_1.Object.zlje[1] = ld_zzlje
	tab_1.tab_gzxx.dw_gzxx.Retrieve(idt_begin,idt_end)
	tab_1.tab_gzxx.dw_gzxx.Object.Title.Text = '改 帐 申 请 [温医附属二院]'
	tab_1.tab_gzxx.dw_gzxx.Object.rq.Text = '日期：'+String(idt_begin,'yyyy-mm-dd')
	dw_toolbar.Enabled = True
	IF dw_1.Object.flag[1] = '3' Or dw_1.Object.flag[1] = '4' THEN
		RETURN
	ELSEIF base_info.qxjb < 2 THEN
		RETURN
	END IF
ELSE
	dw_1.InsertRow(1)
END IF
	gf_waiting('开始校验数据......',1)
	//对在cfk和yjk中社保有记账进行判断
	ll_count1 = 0
	ll_count2 = 0
	ll_count3 = 0
	ll_count4 = 0
	//判断预存是否有过正确结转
	//=======================核对==============================//
	Dec {2} ld_kyc,ld_yck_fp
	ld_kyc = 0
	SELECT SUM(JYJE) Into :ld_kyc From H_MZ_ZHJYMX Where JYSJ >= :idt_begin  And JYSJ < :idt_end And JYLB In (11,12) And Upper(JYDD) Not In ('GH','ZZGH');
	IF IsNull(ld_kyc) THEN ld_kyc = 0
	//====预存款－－扣款fpk,zffs
	ld_yck_fp = 0
	SELECT sum(NVL(H_FP_ZFFS.ZFJE,0)) Into :ld_yck_fp From mz_fpk,H_FP_ZFFS  Where mz_fpk.kpsj >= :idt_begin And mz_fpk.kpsj < :idt_end And (H_FP_ZFFS.zffs = '5') And NVL(mz_fpk.fpzf,0) <> 9  And mz_fpk.fplsh = H_FP_ZFFS.fplsh ;
	IF IsNull(ld_yck_fp) THEN ld_yck_fp = 0
	gf_waiting('正在校验数据......',30)

	IF Abs(ld_kyc+ld_yck_fp) > 1 THEN
		gf_waiting('预存发票未正确结转......',-1)
		MessageBox('提示','预存发票未正确结转，暂时不能统计汇总')
		dw_toolbar.Enabled = True
		SetNull(is_dzr)
		RETURN
	END IF
	//===========自动校对一=================== //
	//判断是否自动校验，再做考虑，2011.04.02
	//	if cbx_sbgz.checked=true then 
	//		wf_auto_jdmz(idt_begin,idt_end)
	//	end if 
	//========================================//
	//------验证门诊数据一致性----社保门诊发票记帐金额-------- //
	Dec {2} ld_sbjzje,ld_mzjz,ld_sdjzje,ld_sbzje,ld_jzce
	SELECT sum(jzje) Into :ld_sbjzje From mz_fpk Where  kpsj >= :idt_begin And kpsj < :idt_end  And  NVL(fpzf,0) <> 9  And jslb In (SELECT brxz From gy_brxz Where ybpb = 1);
	SELECT sum(NVL(jzce,0)) Into :ld_jzce From sb_jejd Where kpsj >= :idt_begin And kpsj < :idt_end And XMLB = 0;
	IF IsNull(ld_jzce) THEN ld_jzce = 0
	ld_sbjzje = ld_sbjzje + ld_jzce
	//+ NVL(tczfs,0) 
	//	IF idt_begin < DateTime(Date(2011,6,27), Time(00:00:00)) THEN
	//		SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0) + NVL(lnzfs,0) +
	//			NVL(tcdtczfs,0) + NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) +
	//			NVL(jzdsgbzfs,0) + NVL(gbzfs,0)   + NVL(jzdjzzfs,0) + NVL(zyjjzfs,0) + NVL(jmjjzf,0) +
	//			NVL(tcdjjzfs,0) + NVL(jzzfs,0) + NVL(qfdlnzhzfs,0) + NVL(jzdslnzhzfs,0) + NVL(tcdlnzhzfs,0))
	//			INTO :ld_mzjz
	//			FROM sb_jymx
	//			Where jssj >= :idt_begin And jssj < :idt_end And  Length(NVL(zxlsh,' ')) > 3  And NVL(zymz,'0') = '0' And (NVL(xmlb,'SF') <> 'GH') And JYLX <> 'SD01';
	//		//sd的退费+ NVL(tczfs,0) 
	//		SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0) + NVL(lnzfs,0) +
	//			NVL(tcdtczfs,0) + NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) +
	//			NVL(jzdsgbzfs,0) + NVL(gbzfs,0)   + NVL(jzdjzzfs,0) + NVL(zyjjzfs,0) + NVL(jmjjzf,0) +
	//			NVL(tcdjjzfs,0) + NVL(jzzfs,0) + NVL(qfdlnzhzfs,0) + NVL(jzdslnzhzfs,0) + NVL(tcdlnzhzfs,0))
	//			INTO :ld_sdjzje
	//			FROM sb_jymx
	//			Where jssj >= :idt_begin And jssj < :idt_end And  Length(NVL(zxlsh,' ')) > 3  And NVL(zymz,'0') = '0' And (NVL(xmlb,'SF') <> 'GH') And JYLX = 'SD01';
	//	ELSE
	SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0) + NVL(lnzfs,0) + 		NVL(tcdtczfs,0) + NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) + 		NVL(jzdsgbzfs,0) + NVL(gbzfs,0)   + NVL(jzdjzzfs,0) + NVL(zyjjzfs,0) + NVL(jmjjzf,0) + 		NVL(tcdjjzfs,0) + NVL(jzzfs,0) + NVL(qfdlnzhzfs,0) + NVL(jzdslnzhzfs,0) + NVL(tcdlnzhzfs,0))
		INTO :ld_mzjz
		FROM sb_jymx
		Where jssj >= :idt_begin And jssj < :idt_end And  zxlsh Is Not Null  And NVL(zymz,'0') = '0' And (NVL(XMLB,'SF') <> 'GH');

	//	END IF
	gf_waiting('正在校验数据......',55)
	IF IsNull(ld_mzjz) THEN ld_mzjz = 0
	IF IsNull(ld_sbjzje) THEN ld_sbjzje = 0
	IF IsNull(ld_sdjzje) THEN ld_sdjzje = 0
	ld_sbzje = ld_mzjz - ld_sdjzje
	IF  ld_sbzje <> ld_sbjzje THEN
		gf_waiting('门诊交易数据不一致......',-1)
		MessageBox('提示,不能对帐，请与计算中心联系','门诊交易数据不一致：mz理论交易(sb_jymx) ：'+String(ld_sbzje)+'  sb实际发生额 (mz_fpk)：'+String(ld_sbjzje)+'  差值：'+String(ld_sbzje - ld_sbjzje))
		dw_toolbar.Enabled = True
//		SetNull(is_dzr)
//		RETURN
	END IF

	//挂号记账金额是否一致验证------------------
	Dec{2} ld_ghjz,ld_sbghjz,ld_sdghjz,ld_ghzje
	SELECT sum(NVL(ZJJE,0) - NVL(XJJE,0)) Into :ld_ghjz From mz_ghxx Where  GHRQ >= :idt_begin And GHRQ < :idt_end  And  (nvl(THBZ,0) Not In ('i','3'))  And jslb In (SELECT brxz From gy_brxz Where ybpb = 1);
	SELECT sum(NVL(jzce,0)) Into :ld_jzce From sb_jejd Where kpsj >= :idt_begin And kpsj < :idt_end And XMLB = 1;
	IF IsNull(ld_jzce) THEN ld_jzce = 0
	ld_ghjz = ld_ghjz + ld_jzce
	//	IF idt_begin < DateTime(Date(2011,6,27), Time(00:00:00)) THEN
	//		//+ NVL(tczfs,0) 
	//		SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0) + NVL(lnzfs,0) +
	//			NVL(tcdtczfs,0) + NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) +
	//			NVL(jzdsgbzfs,0) + NVL(gbzfs,0)   + NVL(jzdjzzfs,0) + NVL(zyjjzfs,0) + NVL(jmjjzf,0) +
	//			NVL(tcdjjzfs,0) + NVL(jzzfs,0) + NVL(qfdlnzhzfs,0) + NVL(jzdslnzhzfs,0) + NVL(tcdlnzhzfs,0))
	//			INTO :ld_sbghjz
	//			FROM sb_jymx
	//			Where jssj >= :idt_begin And jssj < :idt_end And  Length(NVL(zxlsh,' ')) > 3  And NVL(zymz,'0') = '0' And (NVL(xmlb,'SF') = 'GH') And JYLX <> 'SD01';
	//		//sd的退费+ NVL(tczfs,0) 
	//		SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0) + NVL(lnzfs,0) +
	//			NVL(tcdtczfs,0) + NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) +
	//			NVL(jzdsgbzfs,0) + NVL(gbzfs,0)   + NVL(jzdjzzfs,0) + NVL(zyjjzfs,0) + NVL(jmjjzf,0) +
	//			NVL(tcdjjzfs,0) + NVL(jzzfs,0) + NVL(qfdlnzhzfs,0) + NVL(jzdslnzhzfs,0) + NVL(tcdlnzhzfs,0))
	//			INTO :ld_sdghjz
	//			FROM sb_jymx
	//			Where jssj >= :idt_begin And jssj < :idt_end And  Length(NVL(zxlsh,' ')) > 3  And NVL(zymz,'0') = '0' And (NVL(xmlb,'SF') = 'GH') And JYLX = 'SD01';
	//	ELSE
	SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0) + NVL(lnzfs,0) + 		NVL(tcdtczfs,0) + NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) + 		NVL(jzdsgbzfs,0) + NVL(gbzfs,0)   + NVL(jzdjzzfs,0) + NVL(zyjjzfs,0) + NVL(jmjjzf,0) + 		NVL(tcdjjzfs,0) + NVL(jzzfs,0) + NVL(qfdlnzhzfs,0) + NVL(jzdslnzhzfs,0) + NVL(tcdlnzhzfs,0))
		INTO :ld_sbghjz
		FROM sb_jymx
		Where jssj >= :idt_begin And jssj < :idt_end And  zxlsh Is Not Null And NVL(zymz,'0') = '0' And (NVL(XMLB,'SF') = 'GH') ;
	//	END IF
	IF IsNull(ld_ghjz) THEN ld_ghjz = 0
	IF IsNull(ld_sbghjz) THEN ld_sbghjz = 0
	IF IsNull(ld_sdghjz) THEN ld_sdghjz = 0
	ld_ghzje = ld_sbghjz - ld_sdghjz
	IF  ld_ghjz <> ld_ghzje THEN
		gf_waiting('门诊挂号交易数据不一致......',-1)
		MessageBox('提示,不能对帐，请与计算中心联系','门诊挂号数据不一致：mz理论交易(sb_jymx) ：'+String(ld_ghzje)+'  sb实际发生额 (MZ_GHXX)：'+String(ld_ghjz)+'  差值：'+String(ld_ghzje - ld_ghjz))
		dw_toolbar.Enabled = True
		SetNull(is_dzr)
		RETURN
	END IF
	gf_waiting('正在校验数据......',100)

	//------------开始统计数据------------ //
	gf_waiting('开始统计数据......',1)

	//	IF idt_begin < DateTime(Date(2011,6,27), Time(00:00:00)) THEN
	//		SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0)),
	//			sum(NVL(lnzfs,0)  + NVL(qfdlnzhzfs,0) + NVL(tcdlnzhzfs,0) + NVL(jzdlnzhzfs,0) +  NVL(jzdslnzhzfs,0)),
	//			sum(NVL(ybzfxjzfs,0) + NVL(qfdxjzfs,0) + NVL(tcdxjzfs,0) + NVL(jzdxjzfs,0) + NVL(jzdsxjzfs,0) + NVL(jmxjzf,0) + NVL(jmfdxsgrxjzf,0) + NVL(jmqfdxjzf,0) + NVL(qfdgrxjzfs,0) + NVL(tcdfdxsgrxjzfs,0)),
	//			sum(NVL(tcdtczfs,0))  ,
	//			sum(NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) + NVL(jzdsgbzfs,0) + NVL(gbzfs,0)),
	//			sum(NVL(jzdjzzfs,0) + NVL(jzzfs,0)),
	//			sum(NVL(zyjjzfs,0)),
	//			sum(NVL(jmjjzf,0)  + NVL(tcdjjzfs,0) )
	//			INTO :ld_dnzhzfze,:ld_lnzhzfze,:ld_ybzfxjzfze,:ld_tczfze,:ld_gbzfze,:ld_jzzfze,:ld_zyjjzfze,:ld_jmybjjzfze
	//			From sb_jymx Where jssj >= :idt_begin And jssj < :idt_end And  zxlsh Is Not Null And JYLX <> 'SD01';
	//			
	//		SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0)),
	//			sum(NVL(lnzfs,0)  + NVL(qfdlnzhzfs,0) + NVL(tcdlnzhzfs,0) + NVL(jzdlnzhzfs,0) +  NVL(jzdslnzhzfs,0)),
	//			sum(NVL(ybzfxjzfs,0) + NVL(qfdxjzfs,0) + NVL(tcdxjzfs,0) + NVL(jzdxjzfs,0) + NVL(jzdsxjzfs,0) + NVL(jmxjzf,0) + NVL(jmfdxsgrxjzf,0) + NVL(jmqfdxjzf,0) + NVL(qfdgrxjzfs,0) + NVL(tcdfdxsgrxjzfs,0)),
	//			sum(NVL(tcdtczfs,0))  ,
	//			sum(NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) + NVL(jzdsgbzfs,0) + NVL(gbzfs,0)),
	//			sum(NVL(jzdjzzfs,0) + NVL(jzzfs,0)),
	//			sum(NVL(zyjjzfs,0)),
	//			sum(NVL(jmjjzf,0)  + NVL(tcdjjzfs,0) )
	//			INTO :ld_sddnzhzfze,:ld_sdlnzhzfze,:ld_sdybzfxjzfze,:ld_sdtczfze,:ld_sdgbzfze,:ld_sdjzzfze,:ld_sdzyjjzfze,:ld_sdjmybjjzfze
	//			From sb_jymx Where jssj >= :idt_begin And jssj < :idt_end And  zxlsh Is Not Null And JYLX = 'SD01';
	//		ld_zje = ld_dnzhzfze + ld_lnzhzfze + ld_ybzfxjzfze + ld_tczfze + ld_gbzfze + ld_jzzfze + ld_zyjjzfze + ld_jmybjjzfze - (ld_sddnzhzfze+ld_sdlnzhzfze+ld_sdybzfxjzfze+ld_sdtczfze + ld_sdgbzfze + ld_sdjzzfze + ld_sdzyjjzfze + ld_sdjmybjjzfze)
	//	ELSE
	SELECT sum(NVL(dnzfs,0) + NVL(qfddnzhzfs,0)),
		sum(NVL(lnzfs,0)  + NVL(qfdlnzhzfs,0) + NVL(tcdlnzhzfs,0) + NVL(jzdlnzhzfs,0) +  NVL(jzdslnzhzfs,0)),
		sum(NVL(ybzfxjzfs,0) + NVL(qfdxjzfs,0) + NVL(tcdxjzfs,0) + NVL(jzdxjzfs,0) + NVL(jzdsxjzfs,0) + NVL(jmxjzf,0) + NVL(jmfdxsgrxjzf,0) + NVL(jmqfdxjzf,0) + NVL(qfdgrxjzfs,0) + NVL(tcdfdxsgrxjzfs,0)),
		sum(NVL(tcdtczfs,0))  ,
		sum(NVL(qfdgbzfs,0) + NVL(tcdgbzfs,0) + NVL(jzdgbzfs,0) + NVL(jzdsgbzfs,0) + NVL(gbzfs,0)),
		sum(NVL(jzdjzzfs,0) + NVL(jzzfs,0)),
		sum(NVL(zyjjzfs,0)),
		sum(NVL(jmjjzf,0)  + NVL(tcdjjzfs,0) )
		INTO :ld_dnzhzfze,:ld_lnzhzfze,:ld_ybzfxjzfze,:ld_tczfze,:ld_gbzfze,:ld_jzzfze,:ld_zyjjzfze,:ld_jmybjjzfze
		From sb_jymx Where jssj >= :idt_begin And jssj < :idt_end And  zxlsh Is Not Null;
	ld_zje = ld_dnzhzfze + ld_lnzhzfze + ld_ybzfxjzfze + ld_tczfze + ld_gbzfze + ld_jzzfze + ld_zyjjzfze + ld_jmybjjzfze
	//	END IF
	gf_waiting('正在统计数据......',10)
	//门诊+ NVL(tczfs,0) 
