public function decimal wf_getzxjj (long al_materialmanu);//
//  功能:获得最新进价zxjj
//  参数:物品产家add ljp 进价限制时用
//
//
decimal ld_Price

SELECT ZXJJ INTO :ld_Price FROM WZ_WPKC WHERE CKBH=2 AND WPCJ=:al_MaterialManu;
if isNull(ld_Price) or ld_Price<=0 then  
	SELECT JHJG INTO :ld_Price FROM WZ_WPKC WHERE CKBH=2 AND WPCJ=:al_MaterialManu;
	if isNull(ld_Price) or ld_Price<=0 then  //如果还没有最新进价,则取批发价
